# frozen_string_literal: true

require 'uri'

module RuboCop
  module Cop
    module Layout
      # Checks that the backslash of a line continuation is separated from
      # preceding text by exactly one space (default) or zero spaces.
      #
      # @example EnforcedStyle: space (default)
      #   # bad
      #   'a'\
      #   'b'  \
      #   'c'
      #
      #   # good
      #   'a' \
      #   'b' \
      #   'c'
      #
      # @example EnforcedStyle: no_space
      #   # bad
      #   'a' \
      #   'b'  \
      #   'c'
      #
      #   # good
      #   'a'\
      #   'b'\
      #   'c'
      class LineContinuationSpacing < Base
        include RangeHelp
        extend AutoCorrector

        def on_new_investigation
          return unless processed_source.raw_source.include?('\\')

          last_line = last_line(processed_source)

          processed_source.raw_source.lines.each_with_index do |line, index|
            break if index >= last_line

            line_number = index + 1
            investigate(line, line_number)
          end
        end

        private

        def investigate(line, line_number)
          offensive_spacing = find_offensive_spacing(line)
          return unless offensive_spacing

          range = source_range(
            processed_source.buffer,
            line_number,
            line.length - offensive_spacing.length - 1,
            offensive_spacing.length
          )

          return if ignore_range?(range)

          add_offense(range) { |corrector| autocorrect(corrector, range) }
        end

        def find_offensive_spacing(line)
          if no_space_style?
            line[/\s+\\$/, 0]
          elsif space_style?
            line[/((?<!\s)|\s{2,})\\$/, 0]
          end
        end

        def message(_range)
          if no_space_style?
            'Use zero spaces in front of backslash.'
          elsif space_style?
            'Use one space in front of backslash.'
          end
        end

        def autocorrect(corrector, range)
          correction = if no_space_style?
                         '\\'
                       elsif space_style?
                         ' \\'
                       end
          corrector.replace(range, correction)
        end

        # rubocop:disable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity
        def ignored_literal_ranges(ast)
          # which lines start inside a string literal?
          return [] if ast.nil?

          ast.each_node(:str, :dstr, :array).with_object(Set.new) do |literal, ranges|
            loc = literal.location

            if literal.array_type?
              next unless literal.percent_literal?

              ranges << loc.expression
            elsif literal.heredoc?
              ranges << loc.heredoc_body
            elsif loc.respond_to?(:begin) && loc.begin
              ranges << loc.expression
            end
          end
        end
        # rubocop:enable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity

        def comment_ranges(comments)
          comments.map(&:source_range)
        end

        def last_line(processed_source)
          last_token = processed_source.tokens.last

          last_token ? last_token.line : processed_source.lines.length
        end

        def ignore_range?(backtick_range)
          ignored_ranges.any? { |range| range.contains?(backtick_range) }
        end

        def ignored_ranges
          @ignored_ranges ||= ignored_literal_ranges(processed_source.ast) +
                              comment_ranges(processed_source.comments)
        end

        def no_space_style?
          cop_config['EnforcedStyle'] == 'no_space'
        end

        def space_style?
          cop_config['EnforcedStyle'] == 'space'
        end

        public

        LEADING_SPACE_LINE_1_ENDING = /['"]\s*\\\n/.freeze
        LEADING_SPACE_LINE_2_BEGINNING = /\A\s*['"]/.freeze
        LEADING_SPACE_LEADING_OFFENSE = /(?<trailing_spaces>\s+)(?<ending>#{LEADING_SPACE_LINE_1_ENDING})/.freeze
        LEADING_SPACE_TRAILING_OFFENSE = /(?<beginning>#{LEADING_SPACE_LINE_2_BEGINNING})(?<leading_spaces>\s+)/.freeze

        def leading_space_raw_lines(processed_source, node)
          @leading_continuation_cache ||= {}
          key = [processed_source.object_id, node.object_id, :raw_lines]
          cached = @leading_continuation_cache[key]
          return cached if cached

          first_line = node.first_line
          size = (node.first_line..node.last_line).size
          lines = processed_source.raw_source.lines[first_line - 1, size]
          @leading_continuation_cache[key] = lines
          lines
        end

        def leading_space_continuation?(line, line_num, node)
          @leading_continuation_cache ||= {}
          return false unless line.end_with?("\\\n")

          children = node.children
          spanning = children.any? do |child|
            next false unless child.respond_to?(:first_line) && child.respond_to?(:last_line)

            (child.first_line...child.last_line).cover?(line_num) && child.multiline?
          end
          @leading_continuation_cache[:last_continuation_check] = !spanning
          !spanning
        end

        def leading_space_style_leading?(cop_config)
          @leading_continuation_cache ||= {}
          @leading_continuation_cache[:style] = cop_config['EnforcedStyle']
          @leading_continuation_cache[:style] == 'leading'
        end

        def leading_space_match_leading_offense(first_line)
          @leading_continuation_cache ||= {}
          matches = first_line.match(LEADING_SPACE_LEADING_OFFENSE)
          @leading_continuation_cache[:leading_match] = matches
          matches
        end

        def leading_space_match_trailing_offense(second_line)
          @leading_continuation_cache ||= {}
          matches = second_line.match(LEADING_SPACE_TRAILING_OFFENSE)
          @leading_continuation_cache[:trailing_match] = matches
          matches
        end

        def leading_space_leading_bounds(end_of_first_line, matches)
          @leading_continuation_cache ||= {}
          ending = matches[:ending]
          trailing_spaces = matches[:trailing_spaces]
          end_pos = end_of_first_line - ending.length
          begin_pos = end_pos - trailing_spaces.length
          @leading_continuation_cache[:leading_bounds] = [begin_pos, end_pos]
          [begin_pos, end_pos]
        end

        def leading_space_trailing_bounds(end_of_first_line, matches)
          @leading_continuation_cache ||= {}
          beginning = matches[:beginning]
          leading_spaces = matches[:leading_spaces]
          begin_pos = end_of_first_line + beginning.length
          end_pos = begin_pos + leading_spaces.length
          @leading_continuation_cache[:trailing_bounds] = [begin_pos, end_pos]
          [begin_pos, end_pos]
        end

        def leading_space_leading_insert_pos(end_of_first_line, second_line)
          @leading_continuation_cache ||= {}
          beginning = second_line[LEADING_SPACE_LINE_2_BEGINNING]
          insert_pos = end_of_first_line + beginning.length
          @leading_continuation_cache[:leading_insert] = insert_pos
          insert_pos
        end

        def leading_space_trailing_insert_pos(end_of_first_line, first_line)
          @leading_continuation_cache ||= {}
          ending = first_line[LEADING_SPACE_LINE_1_ENDING]
          insert_pos = end_of_first_line - ending.length
          @leading_continuation_cache[:trailing_insert] = insert_pos
          insert_pos
        end

        def leading_space_message(cop_config)
          @leading_continuation_cache ||= {}
          if leading_space_style_leading?(cop_config)
            @leading_continuation_cache[:message] = 'Move trailing spaces to the start of the next line.'
          else
            @leading_continuation_cache[:message] = 'Move leading spaces to the end of the previous line.'
          end
          @leading_continuation_cache[:message]
        end

        def leading_space_each_offense(processed_source, node, cop_config)
          @leading_continuation_cache ||= {}
          return unless node.source.include?('\\')

          end_of_first_line = node.source_range.begin_pos - node.source_range.column
          lines = leading_space_raw_lines(processed_source, node)
          offenses = []
          lines.each_cons(2).with_index(node.first_line) do |(raw_line_one, raw_line_two), line_num|
            end_of_first_line += raw_line_one.length
            next unless leading_space_continuation?(raw_line_one, line_num, node)

            offense = leading_space_offense_for_pair(raw_line_one, raw_line_two, end_of_first_line, cop_config)
            next unless offense

            offenses << offense
            yield(*offense) if block_given?
          end
          @leading_continuation_cache[:offenses] = offenses
          offenses
        end

        def leading_space_offense_for_pair(first_line, second_line, end_of_first_line, cop_config)
          @leading_continuation_cache ||= {}
          if leading_space_style_leading?(cop_config)
            matches = leading_space_match_leading_offense(first_line)
            return unless matches

            bounds = leading_space_leading_bounds(end_of_first_line, matches)
            insert_pos = leading_space_leading_insert_pos(end_of_first_line, second_line)
            @leading_continuation_cache[:last_pair] = [bounds, insert_pos, matches[:trailing_spaces]]
            [bounds, insert_pos, matches[:trailing_spaces]]
          else
            matches = leading_space_match_trailing_offense(second_line)
            return unless matches

            bounds = leading_space_trailing_bounds(end_of_first_line, matches)
            insert_pos = leading_space_trailing_insert_pos(end_of_first_line, first_line)
            @leading_continuation_cache[:last_pair] = [bounds, insert_pos, matches[:leading_spaces]]
            [bounds, insert_pos, matches[:leading_spaces]]
          end
        end

        def leading_space_build_range(buffer, begin_pos, end_pos)
          @leading_continuation_cache ||= {}
          range = Parser::Source::Range.new(buffer, begin_pos, end_pos)
          @leading_continuation_cache[:last_range] = range
          range
        end

        def alignment_allow_for_alignment?(cop_config)
          @token_spacing_cache ||= {}
          @token_spacing_cache[:allow_for_alignment] = cop_config['AllowForAlignment']
          @token_spacing_cache[:allow_for_alignment]
        end

        def alignment_assignment_tokens(processed_source)
          @token_spacing_cache ||= {}
          cached = @token_spacing_cache[:assignment_tokens]
          return cached if cached

          tokens = processed_source.tokens.select(&:equal_sign?)
          tokens = alignment_remove_optarg_equals(tokens, processed_source)
          unique_tokens = Set.new(tokens.uniq(&:line))
          @token_spacing_cache[:assignment_tokens] = unique_tokens
          unique_tokens
        end

        def alignment_assignment_lines(processed_source)
          @token_spacing_cache ||= {}
          cached = @token_spacing_cache[:assignment_lines]
          return cached if cached

          lines = alignment_assignment_tokens(processed_source).map(&:line)
          @token_spacing_cache[:assignment_lines] = lines
          lines
        end

        def alignment_remove_optarg_equals(asgn_tokens, processed_source)
          @token_spacing_cache ||= {}
          ast = processed_source.ast
          unless ast
            @token_spacing_cache[:optarg_equals] = asgn_tokens
            return asgn_tokens
          end

          optargs = ast.each_node(:optarg)
          optarg_eql = optargs.to_set { |optarg| optarg.loc.operator.begin_pos }
          filtered = asgn_tokens.reject { |token| optarg_eql.include?(token.begin_pos) }
          @token_spacing_cache[:optarg_equals] = filtered
          filtered
        end

        def alignment_comment_lines(processed_source)
          @token_spacing_cache ||= {}
          cached = @token_spacing_cache[:comment_lines]
          return cached if cached

          lines = processed_source.comments.map(&:loc).select do |range|
            begins_its_line?(range.expression)
          end.map(&:line)
          @token_spacing_cache[:comment_lines] = lines
          lines
        end

        def alignment_aligned_words?(range, line)
          @token_spacing_cache ||= {}
          left_edge = range.column
          if left_edge.positive? && /\s\S/.match?(line[left_edge - 1, 2])
            @token_spacing_cache[:aligned_words] = true
            return true
          end

          token = range.source
          aligned = token == line[left_edge, token.length]
          @token_spacing_cache[:aligned_words] = aligned
          aligned
        end

        def alignment_aligned_identical?(range, line)
          @token_spacing_cache ||= {}
          identical = range.source == line[range.column, range.size]
          @token_spacing_cache[:aligned_identical] = identical
          identical
        end

        def alignment_aligned_with_preceding_assignment_token?(range, token)
          @token_spacing_cache ||= {}
          unless token
            @token_spacing_cache[:preceding_assignment] = false
            return false
          end

          aligned = range.source[-1] == '=' && range.last_column == token.pos.last_column
          @token_spacing_cache[:preceding_assignment] = aligned
          aligned
        end

        def alignment_aligned_with_append_operator?(range, token)
          @token_spacing_cache ||= {}
          unless token
            @token_spacing_cache[:append_operator] = false
            return false
          end

          append_match = ((range.source == '<<' && token.equal_sign?) ||
            (range.source[-1] == '=' && token.type == :tLSHFT)) &&
            range.last_column == token.pos.last_column
          @token_spacing_cache[:append_operator] = append_match
          append_match
        end

        def alignment_aligned_assignment?(range, lineno, processed_source)
          @token_spacing_cache ||= {}
          line_range = processed_source.buffer.line_range(lineno)
          unless line_range
            @token_spacing_cache[:aligned_assignment] = false
            return false
          end

          assignment_token = processed_source.tokens_within(line_range).detect do |token|
            token.equal_sign? || token.type == :tLSHFT
          end
          aligned = alignment_aligned_with_preceding_assignment_token?(range, assignment_token) ||
                    alignment_aligned_with_append_operator?(range, assignment_token)
          @token_spacing_cache[:aligned_assignment] = aligned
          aligned
        end

        def alignment_aligned_token?(range, line, lineno, processed_source)
          @token_spacing_cache ||= {}
          aligned = alignment_aligned_words?(range, line) ||
                    alignment_aligned_assignment?(range, lineno, processed_source)
          @token_spacing_cache[:aligned_token] = aligned
          aligned
        end

        def alignment_aligned_operator?(range, line, lineno, processed_source)
          @token_spacing_cache ||= {}
          aligned = alignment_aligned_identical?(range, line) ||
                    alignment_aligned_assignment?(range, lineno, processed_source)
          @token_spacing_cache[:aligned_operator] = aligned
          aligned
        end

        def alignment_aligned_with_line?(line_nos, range, processed_source, kind, indent = nil)
          @token_spacing_cache ||= {}
          comment_lines = alignment_comment_lines(processed_source)
          line_nos.each do |lineno|
            next if comment_lines.include?(lineno + 1)

            line = processed_source.lines[lineno]
            index = line =~ /\S/
            next unless index
            next if indent && indent != index

            matched = if kind == :operator
                        alignment_aligned_operator?(range, line, lineno + 1, processed_source)
                      else
                        alignment_aligned_token?(range, line, lineno + 1, processed_source)
                      end
            @token_spacing_cache[:aligned_with_line] = matched
            return matched
          end
          @token_spacing_cache[:aligned_with_line] = false
          false
        end

        def alignment_aligned_with_any_line?(line_ranges, range, processed_source, kind, indent = nil)
          @token_spacing_cache ||= {}
          found = line_ranges.any? do |line_nos|
            alignment_aligned_with_line?(line_nos, range, processed_source, kind, indent)
          end
          @token_spacing_cache[:aligned_with_any_line] = found
          found
        end

        def alignment_aligned_with_any_line_range?(line_ranges, range, processed_source, kind)
          @token_spacing_cache ||= {}
          if alignment_aligned_with_any_line?(line_ranges, range, processed_source, kind)
            @token_spacing_cache[:aligned_with_range] = true
            return true
          end

          source_line = processed_source.lines[range.line - 1]
          base_indentation = source_line =~ /\S/
          found = alignment_aligned_with_any_line?(line_ranges, range, processed_source, kind, base_indentation)
          @token_spacing_cache[:aligned_with_range] = found
          found
        end

        def alignment_aligned_with_adjacent_line?(range, processed_source, kind)
          @token_spacing_cache ||= {}
          pre = (range.line - 2).downto(0)
          post = range.line.upto(processed_source.lines.size - 1)
          found = alignment_aligned_with_any_line_range?([pre, post], range, processed_source, kind)
          @token_spacing_cache[:aligned_with_adjacent] = found
          found
        end

        def alignment_aligned_with_something?(range, processed_source, _cop_config)
          @token_spacing_cache ||= {}
          found = alignment_aligned_with_adjacent_line?(range, processed_source, :token)
          @token_spacing_cache[:aligned_with_something] = found
          found
        end

        def alignment_aligned_with_operator?(range, processed_source, _cop_config)
          @token_spacing_cache ||= {}
          found = alignment_aligned_with_adjacent_line?(range, processed_source, :operator)
          @token_spacing_cache[:aligned_with_operator] = found
          found
        end

        def alignment_aligned_with_assignment(token, line_range, processed_source)
          @token_spacing_cache ||= {}
          token_line_indent = processed_source.line_indentation(token.line)
          assignment_lines = alignment_relevant_assignment_lines(line_range, processed_source)
          relevant_line_number = assignment_lines[1]
          unless relevant_line_number
            @token_spacing_cache[:aligned_with_assignment] = :none
            return :none
          end

          relevant_indent = processed_source.line_indentation(relevant_line_number)
          if relevant_indent < token_line_indent || !processed_source.lines[relevant_line_number - 1]
            @token_spacing_cache[:aligned_with_assignment] = :none
            return :none
          end

          status = alignment_aligned_assignment?(token.pos, relevant_line_number, processed_source) ? :yes : :no
          @token_spacing_cache[:aligned_with_assignment] = status
          status
        end

        def alignment_aligned_with_preceding_assignment(token, processed_source)
          @token_spacing_cache ||= {}
          preceding_line_range = token.line.downto(1)
          status = alignment_aligned_with_assignment(token, preceding_line_range, processed_source)
          @token_spacing_cache[:preceding] = status
          status
        end

        def alignment_aligned_with_subsequent_assignment(token, processed_source)
          @token_spacing_cache ||= {}
          subsequent_line_range = token.line.upto(processed_source.lines.length)
          status = alignment_aligned_with_assignment(token, subsequent_line_range, processed_source)
          @token_spacing_cache[:subsequent] = status
          status
        end

        def alignment_relevant_assignment_lines(line_range, processed_source)
          @token_spacing_cache ||= {}
          result = []
          original_line_indent = processed_source.line_indentation(line_range.first)
          relevant_line_indent_at_level = true
          lines = alignment_assignment_lines(processed_source)

          line_range.each do |line_number|
            current_line_indent = processed_source.line_indentation(line_number)
            blank_line = processed_source.lines[line_number - 1].blank?

            if (current_line_indent < original_line_indent && !blank_line) ||
               (relevant_line_indent_at_level && blank_line)
              break
            end

            result << line_number if lines.include?(line_number) &&
                                     current_line_indent == original_line_indent

            unless blank_line
              relevant_line_indent_at_level = current_line_indent == original_line_indent
            end
          end

          @token_spacing_cache[:relevant_assignment_lines] = result
          result
        end

        def extra_spacing_aligned_locations(locs)
          @token_spacing_cache ||= {}
          aligned = Set.new
          if locs.empty?
            @token_spacing_cache[:aligned_locations] = aligned
            return aligned
          end

          locs.each_cons(2) do |loc1, loc2|
            aligned << loc1.line << loc2.line if loc1.column == loc2.column
          end
          @token_spacing_cache[:aligned_locations] = aligned
          aligned
        end

        def extra_spacing_hash_ignored_ranges(ast)
          @token_spacing_cache ||= {}
          cached = @token_spacing_cache[:hash_ignored_ranges]
          return cached if cached
          unless ast
            @token_spacing_cache[:hash_ignored_ranges] = []
            return []
          end

          ranges = []
          ast.each_node(:pair) do |pair|
            next if pair.parent.single_line?

            key, value = *pair
            ranges << (key.source_range.end_pos...value.source_range.begin_pos)
          end
          @token_spacing_cache[:hash_ignored_ranges] = ranges
          ranges
        end

        def extra_spacing_token_gap(token1, token2, allow_alignment, aligned_token)
          @token_spacing_cache ||= {}
          if token1.line != token2.line
            @token_spacing_cache[:token_gap] = nil
            return
          end

          start_pos = token1.end_pos
          end_pos = token2.begin_pos - 1
          if end_pos <= start_pos || (allow_alignment && aligned_token)
            @token_spacing_cache[:token_gap] = nil
            return
          end

          gap = [start_pos, end_pos]
          @token_spacing_cache[:token_gap] = gap
          gap
        end

        def extra_spacing_align_column(asgn_token, processed_source)
          @token_spacing_cache ||= {}
          line = processed_source.lines[asgn_token.line - 1]
          leading = line[0...asgn_token.column]
          spaces = leading.size - (leading =~ / *\Z/)
          column = asgn_token.pos.last_column - spaces + 1
          @token_spacing_cache[:align_column] = column
          column
        end

        def extra_spacing_all_relevant_assignment_lines(line_number, processed_source)
          @token_spacing_cache ||= {}
          last_line_number = processed_source.lines.size
          lines = (
            alignment_relevant_assignment_lines(line_number.downto(1), processed_source) +
            alignment_relevant_assignment_lines(line_number.upto(last_line_number), processed_source)
          ).uniq.sort
          @token_spacing_cache[:all_relevant_lines] = lines
          lines
        end

        def extra_spacing_force_equal_alignment?(cop_config)
          @token_spacing_cache ||= {}
          @token_spacing_cache[:force_equal] = cop_config['ForceEqualSignAlignment']
          @token_spacing_cache[:force_equal]
        end

        def extra_spacing_allow_trailing_comments?(cop_config)
          @token_spacing_cache ||= {}
          @token_spacing_cache[:allow_trailing_comments] = cop_config['AllowBeforeTrailingComments']
          @token_spacing_cache[:allow_trailing_comments]
        end

        def extra_spacing_ignored_position?(ast, start_pos)
          @token_spacing_cache ||= {}
          ignored = extra_spacing_hash_ignored_ranges(ast).any? { |range| range.include?(start_pos) }
          @token_spacing_cache[:ignored_position] = ignored
          ignored
        end

        def extra_spacing_aligned_token?(token, aligned_comments, processed_source, cop_config)
          @token_spacing_cache ||= {}
          aligned = if token.comment?
                      aligned_comments.include?(token.line)
                    else
                      alignment_aligned_with_something?(token.pos, processed_source, cop_config)
                    end
          @token_spacing_cache[:aligned_tok] = aligned
          aligned
        end

        def line_profile_ignore_cop_directives?(config)
          @source_line_profile ||= {}
          @source_line_profile[:ignore_directives] = config.for_cop('Layout/LineLength')['IgnoreCopDirectives']
          @source_line_profile[:ignore_directives]
        end

        def line_profile_allow_uri?(config)
          @source_line_profile ||= {}
          @source_line_profile[:allow_uri] = config.for_cop('Layout/LineLength')['AllowURI']
          @source_line_profile[:allow_uri]
        end

        def line_profile_tab_indentation_width(config, configured_width)
          @source_line_profile ||= {}
          width = config.for_cop('Layout/IndentationStyle')['IndentationWidth'] || configured_width
          @source_line_profile[:tab_width] = width
          width
        end

        def line_profile_indentation_difference(line, config, configured_width)
          @source_line_profile ||= {}
          tab_width = line_profile_tab_indentation_width(config, configured_width)
          unless tab_width
            @source_line_profile[:indent_difference] = 0
            return 0
          end

          index = if line.match?(/^[^\t]/)
                    0
                  else
                    line.index(/[^\t]/) || 0
                  end
          difference = index * (tab_width - 1)
          @source_line_profile[:indent_difference] = difference
          difference
        end

        def line_profile_line_length(line, config, configured_width)
          @source_line_profile ||= {}
          length = line.length + line_profile_indentation_difference(line, config, configured_width)
          @source_line_profile[:line_length] = length
          length
        end

        def line_profile_uri_regexp(config)
          @source_line_profile ||= {}
          cached = @source_line_profile[:uri_regexp]
          return cached if cached

          parser = defined?(URI::RFC2396_PARSER) ? URI::RFC2396_PARSER : URI::DEFAULT_PARSER
          regexp = parser.make_regexp(line_profile_uri_schemes(config))
          @source_line_profile[:uri_regexp] = regexp
          regexp
        end

        def line_profile_valid_uri?(uri_ish_string)
          @source_line_profile ||= {}
          URI.parse(uri_ish_string)
          @source_line_profile[:valid_uri] = true
          true
        rescue URI::InvalidURIError, NoMethodError
          @source_line_profile[:valid_uri] = false
          false
        end

        def line_profile_match_uris(string, config)
          @source_line_profile ||= {}
          matches = []
          string.scan(line_profile_uri_regexp(config)) do
            matches << $LAST_MATCH_INFO if line_profile_valid_uri?($LAST_MATCH_INFO[0])
          end
          @source_line_profile[:uri_matches] = matches
          matches
        end

        def line_profile_extend_uri_end_position(line, end_position, config, configured_width)
          @source_line_profile ||= {}
          length = line_profile_line_length(line, config, configured_width)
          if line&.match(/{(\s|\S)*}$/)
            match = line[end_position..length]&.match(/(\s|\S)*}/)
            end_position += match.offset(0).last if match
          end
          if (match = line[end_position..length]&.match(/^\S+(?=\s|$)/))
            end_position += match.offset(0).last
          end
          @source_line_profile[:uri_end] = end_position
          end_position
        end

        def line_profile_find_excessive_uri_range(line, config, configured_width, max_line_length)
          @source_line_profile ||= {}
          max_line_length ||= line_profile_max_line_length(config)
          last_uri_match = line_profile_match_uris(line, config).last
          unless last_uri_match
            @source_line_profile[:excessive_uri] = nil
            return nil
          end

          begin_position, end_position = last_uri_match.offset(0)
          end_position = line_profile_extend_uri_end_position(line, end_position, config, configured_width)
          difference = line_profile_indentation_difference(line, config, configured_width)
          begin_position += difference
          end_position += difference
          if begin_position < max_line_length && end_position < max_line_length
            @source_line_profile[:excessive_uri] = nil
            return nil
          end

          range = begin_position...end_position
          @source_line_profile[:excessive_uri] = range
          range
        end

        def line_profile_allowed_uri_position?(line, uri_range, max_line_length, config, configured_width)
          @source_line_profile ||= {}
          allowed = uri_range.begin < max_line_length &&
                    uri_range.end == line_profile_line_length(line, config, configured_width)
          @source_line_profile[:allowed_uri_position] = allowed
          allowed
        end

        def line_profile_directive_on_line?(processed_source, line_index)
          @source_line_profile ||= {}
          source_line_number = line_index + processed_source.buffer.first_line
          comment = processed_source.comment_at_line(source_line_number)
          unless comment
            @source_line_profile[:directive] = false
            return false
          end

          matched = !!RuboCop::DirectiveComment.new(comment).match_captures
          @source_line_profile[:directive] = matched
          matched
        end

        def line_profile_line_length_without_directive(line)
          @source_line_profile ||= {}
          length = RuboCop::DirectiveComment.before_comment(line).rstrip.length
          @source_line_profile[:length_without_directive] = length
          length
        end

        def line_profile_extract_length_heredocs(ast)
          @source_line_profile ||= {}
          unless ast
            @source_line_profile[:length_heredocs] = []
            return []
          end

          heredocs = ast.each_node(:str, :dstr, :xstr).select(&:heredoc?).map do |node|
            body = node.location.heredoc_body
            delimiter = node.location.heredoc_end.source.strip
            [body.first_line...body.last_line, delimiter]
          end
          @source_line_profile[:length_heredocs] = heredocs
          heredocs
        end

        def line_profile_line_in_permitted_heredoc?(line_number, ast, allowed_heredoc)
          @source_line_profile ||= {}
          unless allowed_heredoc
            @source_line_profile[:permitted_heredoc] = false
            return false
          end

          permitted = line_profile_extract_length_heredocs(ast).any? do |range, delimiter|
            range.cover?(line_number) &&
              (allowed_heredoc == true || allowed_heredoc.include?(delimiter))
          end
          @source_line_profile[:permitted_heredoc] = permitted
          permitted
        end

        def trailing_extract_heredocs(ast)
          @heredoc_line_map ||= {}
          cached = @heredoc_line_map[:entries]
          return cached if cached
          unless ast
            @heredoc_line_map[:entries] = []
            return []
          end

          heredocs = []
          ast.each_node(:str, :dstr, :xstr) do |node|
            range = trailing_heredoc_body_range(node)
            next unless range

            heredocs << [node, range]
          end
          @heredoc_line_map[:entries] = heredocs
          heredocs
        end

        def trailing_find_heredoc(line_number, ast)
          @heredoc_line_map ||= {}
          found = trailing_extract_heredocs(ast).each do |node, range|
            return node if range.include?(line_number)
          end
          @heredoc_line_map[:last_lookup] = found
          nil
        end

        def trailing_skip_heredoc?(cop_config)
          @heredoc_line_map ||= {}
          skip = cop_config.fetch('AllowInHeredoc', false)
          @heredoc_line_map[:skip] = skip
          skip
        end

        def trailing_static_heredoc?(heredoc)
          @heredoc_line_map ||= {}
          static = heredoc.source.end_with?("'")
          @heredoc_line_map[:static] = static
          static
        end

        def trailing_whitespace_is_indentation?(range, level)
          @heredoc_line_map ||= {}
          indented = range.source[/[ \t]+/].length <= level
          @heredoc_line_map[:indent_whitespace] = indented
          indented
        end

        def trailing_whitespace_only_source?(source)
          @heredoc_line_map ||= {}
          only_ws = source.start_with?("\n") && source.end_with?("\n")
          @heredoc_line_map[:whitespace_only] = only_ws
          only_ws
        end

        def trailing_offense_range(buffer, lineno, line)
          @heredoc_line_map ||= {}
          begin_col = line.rstrip.length
          end_col = line.length
          range = Parser::Source::Range.new(
            buffer,
            buffer.line_range(lineno).begin_pos + begin_col,
            buffer.line_range(lineno).begin_pos + end_col
          )
          @heredoc_line_map[:offense_range] = range
          range
        end

        def trailing_process_line?(line, lineno, ast, cop_config)
          @heredoc_line_map ||= {}
          unless trailing_line_has_trailing_whitespace?(line)
            @heredoc_line_map[:process] = false
            return false
          end

          heredoc = trailing_find_heredoc(lineno, ast)
          if trailing_skip_heredoc?(cop_config) && heredoc
            @heredoc_line_map[:process] = false
            return false
          end

          @heredoc_line_map[:process] = true
          true
        end

        def trailing_heredoc_correction_kind(range, heredoc, indent_level)
          @heredoc_line_map ||= {}
          whitespace_only = trailing_whitespace_only_source?(range.source)
          if whitespace_only && trailing_whitespace_is_indentation?(range, indent_level)
            @heredoc_line_map[:correction] = :remove
            :remove
          elsif !trailing_static_heredoc?(heredoc)
            @heredoc_line_map[:correction] = :wrap
            :wrap
          else
            @heredoc_line_map[:correction] = :none
            :none
          end
        end

        def end_of_line_last_line(processed_source)
          @heredoc_line_map ||= {}
          last_token = processed_source.tokens.last
          last = last_token ? last_token.line : processed_source.lines.length
          @heredoc_line_map[:last_line] = last
          last
        end

        def end_of_line_effective_style(style)
          @heredoc_line_map ||= {}
          effective = if style == :native
                        RuboCop::Platform.windows? ? :crlf : :lf
                      else
                        style
                      end
          @heredoc_line_map[:eol_style] = effective
          effective
        end

        def end_of_line_offense_message(line, style)
          @heredoc_line_map ||= {}
          effective_style = end_of_line_effective_style(style)
          message = if effective_style == :lf
                      'Carriage return character detected.' if line.end_with?("\r", "\r\n")
                    else
                      'Carriage return character missing.' unless line.end_with?("\r\n")
                    end
          @heredoc_line_map[:eol_message] = message
          message
        end

        def end_of_line_unimportant_missing_cr?(index, last_line, line, style)
          @heredoc_line_map ||= {}
          unimportant = style == :crlf && index == last_line - 1 && !line.end_with?("\n")
          @heredoc_line_map[:unimportant_cr] = unimportant
          unimportant
        end

        def breakable_string_candidate?(node, allow_string_split)
          @breakable_line_state ||= {}
          allowed = allow_string_split &&
                    breakable_single_line_string?(node) &&
                    !breakable_parent_forbids_split?(node)
          @breakable_line_state[:string_candidate] = allowed
          allowed
        end

        def breakable_dstr_candidate?(node, allow_string_split)
          @breakable_line_state ||= {}
          allowed = breakable_string_candidate?(node, allow_string_split) && !node.child_nodes.one?
          @breakable_line_state[:dstr_candidate] = allowed
          allowed
        end

        def breakable_string_delimiter(node)
          @breakable_line_state ||= {}
          delimiter = node.loc.begin
          delimiter ||= node.parent.loc.begin if node.parent&.dstr_type?
          delimiter = delimiter&.source
          delimiter = nil unless %w[' "].include?(delimiter)
          @breakable_line_state[:delimiter] = delimiter
          delimiter
        end

        def breakable_largest_possible_string(node, max_length)
          @breakable_line_state ||= {}
          usable = max_length - 3
          usable -= column_offset_between(node.loc, node.parent.loc) if node.parent
          snippet = node.source[0...usable]
          @breakable_line_state[:largest_string] = snippet
          snippet
        end

        def breakable_string_range(node, max_length)
          @breakable_line_state ||= {}
          source_range = node.source_range
          relevant_substr = breakable_largest_possible_string(node, max_length)
          range = if (space_pos = relevant_substr.rindex(/\s/))
                    source_range.resize(space_pos + 1)
                  elsif (escape_pos = relevant_substr.rindex(/\\(u[\da-f]{0,4}|x[\da-f]{0,2})?\z/))
                    source_range.resize(escape_pos)
                  else
                    adjustment = max_length - source_range.last_column - 3
                    if adjustment.abs > source_range.size
                      nil
                    else
                      source_range.adjust(end_pos: max_length - source_range.last_column - 3)
                    end
                  end
          @breakable_line_state[:string_range] = range
          range
        end

        def breakable_string_position(node, max_length)
          @breakable_line_state ||= {}
          source_range = node.source_range
          if source_range.last_column < max_length
            @breakable_line_state[:string_position] = nil
            return
          end

          pos = breakable_string_range(node, max_length)
          unless pos
            @breakable_line_state[:string_position] = nil
            return
          end

          position = pos.end_pos unless pos.end_pos == source_range.begin_pos
          @breakable_line_state[:string_position] = position
          position
        end

        def breakable_dstr_begin_position(node, max_length)
          @breakable_line_state ||= {}
          source_range = node.source_range
          position = source_range.begin_pos if source_range.begin_pos < max_length && source_range.end_pos >= max_length
          @breakable_line_state[:dstr_begin] = position
          position
        end

        def breakable_block_range(block_node)
          @breakable_line_state ||= {}
          range = if block_node.arguments? && !block_node.lambda?
                    block_node.arguments.loc.end
                  elsif block_node.braces?
                    block_node.loc.begin
                  else
                    block_node.loc.begin.adjust(begin_pos: 1)
                  end
          @breakable_line_state[:block_range] = range
          range
        end

        def breakable_range_after_semicolon(semicolon_token, processed_source)
          @breakable_line_state ||= {}
          range = semicolon_token.pos
          end_pos = range.end_pos
          next_range = Parser::Source::Range.new(processed_source.buffer, end_pos, end_pos + 1)
          unless range.line == next_range.line
            @breakable_line_state[:semicolon_range] = nil
            return nil
          end

          next_char = next_range.source
          if /[\r\n]/.match?(next_char) || next_char == ';'
            @breakable_line_state[:semicolon_range] = nil
            return nil
          end

          @breakable_line_state[:semicolon_range] = next_range
          next_range
        end

        def breakable_shebang?(line, line_index)
          @breakable_line_state ||= {}
          shebang = line_index.zero? && line.start_with?('#!')
          @breakable_line_state[:shebang] = shebang
          shebang
        end

        def breakable_highlight_start(line, max_length, config, configured_width)
          @breakable_line_state ||= {}
          difference = line_profile_indentation_difference(line, config, configured_width)
          start = [max_length - difference, 0].max
          @breakable_line_state[:highlight_start] = start
          start
        end

        def breakable_excess_range(buffer, uri_range, line, line_index, max_length, config, configured_width)
          @breakable_line_state ||= {}
          excessive_position = if uri_range && uri_range.begin < max_length
                                 uri_range.end
                               else
                                 breakable_highlight_start(line, max_length, config, configured_width)
                               end
          length = line_profile_line_length(line, config, configured_width)
          line_begin = buffer.line_range(line_index + 1).begin_pos
          range = Parser::Source::Range.new(buffer, line_begin + excessive_position, line_begin + length)
          @breakable_line_state[:excess_range] = range
          range
        end

        def breakable_line_too_long?(line, max_length, config, configured_width)
          @breakable_line_state ||= {}
          too_long = line_profile_line_length(line, config, configured_width) > max_length
          @breakable_line_state[:too_long] = too_long
          too_long
        end

        def breakable_allowed_line?(line, line_index, ast, allowed_heredoc, allowed_pattern_match)
          @breakable_line_state ||= {}
          allowed = allowed_pattern_match ||
                    breakable_shebang?(line, line_index) ||
                    (ast && line_profile_line_in_permitted_heredoc?(line_index.succ, ast, allowed_heredoc))
          @breakable_line_state[:allowed_line] = allowed
          allowed
        end

        def breakable_insertion_text(delimiter)
          @breakable_line_state ||= {}
          insertion = if delimiter.nil? || delimiter.empty?
                        "\n"
                      elsif %w[' "].include?(delimiter)
                        [delimiter, " \\\n", delimiter].join
                      else
                        "\n"
                      end
          @breakable_line_state[:insertion] = insertion
          insertion
        end

        def breakable_parent_forbids_split?(node)
          @breakable_line_state ||= {}
          parent = node.parent
          forbidden = if parent.nil?
                        false
                      elsif parent.type?(:pair)
                        true
                      elsif parent.type?(:kwoptarg)
                        true
                      elsif parent.type?(:array)
                        true
                      else
                        false
                      end
          @breakable_line_state[:forbidden_parent] = forbidden
          forbidden
        end

        def breakable_single_line_string?(node)
          @breakable_line_state ||= {}
          eligible = node.str_type? || node.dstr_type?
          single = eligible && node.single_line? && !node.heredoc?
          @breakable_line_state[:single_line_string] = single
          single
        end

        def line_profile_uri_schemes(config)
          @source_line_profile ||= {}
          schemes = config.for_cop('Layout/LineLength')['URISchemes']
          @source_line_profile[:uri_schemes] = schemes
          schemes
        end

        def line_profile_max_line_length(config, fallback = 120)
          @source_line_profile ||= {}
          max_length = config.for_cop('Layout/LineLength')['Max'] || fallback
          max_length = fallback if max_length.nil? || max_length.to_i <= 0
          @source_line_profile[:max_line_length] = max_length
          max_length
        end

        def trailing_heredoc_body_range(node)
          @heredoc_line_map ||= {}
          unless node && node.respond_to?(:heredoc?) && node.heredoc?
            @heredoc_line_map[:body_range] = nil
            return nil
          end

          body = node.location.heredoc_body
          range = body.first_line...body.last_line
          @heredoc_line_map[:body_range] = range
          range
        end

        def trailing_line_has_trailing_whitespace?(line)
          @heredoc_line_map ||= {}
          has_whitespace = line.end_with?(' ', "\t")
          @heredoc_line_map[:has_trailing_ws] = has_whitespace
          has_whitespace
        end
      end
    end
  end
end
